    if (shouldInline) {
      ret.toString = function() { return "Rule.KeepOnly(" + JSON.stringify(names) + ", true)"; };
    } else {
      ret.toString = function() { return "Rule.KeepOnly(" + JSON.stringify(names) + ")"; };
    }
