    if (this.rule)
      ruleAmbig = this.rule.toString();
    else if (this.ambig)
      ruleAmbig = "ambig";
    else if (this.label instanceof Token)
      ruleAmbig = "<Token " + this.label.toString(true) + ">";
    else
      ruleAmbig = "<unknown>";
    return "SPPFNode(" + this.sppfId + ", " + this.label.toString(true) + "@" + posString + " " + ruleAmbig + ")";
